namespace ghidra.pcodeCPort.context;

public class Token {

	private string name;
	private int size; // Number of bytes in token;
	private int index; // Index of this token, for resolving offsets
	private bool bigendian;

	public Token( string nm, int sz, bool be, int ind ) {
		name = nm;
		size = sz;
		bigendian = be;
		index = ind;
	}

	public int getSize() {
		return size;
	}

	public bool isBigEndian() {
		return bigendian;
	}

	public int getIndex() {
		return index;
	}

	public string getName() {
		return name;
	}

	/* @Override */
    public string toString() {
	    return "Token{" + name + ":" + size + ":" + index + ":" + (bigendian ? "big" : "little") + "}";
	}
}
